fast_pseudocode:
# Single-pass softmax reusing exp
@triton.autotune(configs=[Config({'XBLOCK':1},num_warps=4), Config({'XBLOCK':2},num_warps=4), ...], key=['xnumel','r0_numel'])
@triton.jit
def kernel(...):
    max_val = triton_helpers.max2(scores, 1)[:, None]  # pass 1
    exp_shifted = tl.exp(scores - max_val)             # exp ONCE
    sum_val = tl.sum(exp_shifted, 1)[:, None]
    out = exp_shifted / sum_val                        # reuse, no second exp

