@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 1}, num_warps=2, num_stages=1),
        triton.Config({'XBLOCK': 1}, num_warps=4, num_stages=2),
        triton.Config({'XBLOCK': 1}, num_warps=4, num_stages=3),
        triton.Config({'XBLOCK': 2}, num_warps=8, num_stages=3),
        # ... 12 configs total
    ],
    key=['xnumel', 'r0_numel'],
)
@triton.jit
def kernel(in_out_ptr0, in_ptr0, ...):
    tmp0 = tl.load(in_out_ptr0 + (x0 + stride*r0_2 + ...), xmask,
                   eviction_policy='evict_first', other=0.0)  # evict_first added

